<?php ($fieldId = 'field-'.\Illuminate\Support\Str::random(8)); ?>
<div class="field"><label for="<?php echo e($fieldId); ?>"><?php echo e($label); ?></label>
<?php if(isset($options)): ?><select id="<?php echo e($fieldId); ?>" name="<?php echo e($name); ?>" <?php if($required ?? true): echo 'required'; endif; ?>><?php $__currentLoopData = $options; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $key=>$text): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($key); ?>" <?php if((string)($value ?? '')===(string)$key): echo 'selected'; endif; ?>><?php echo e($text); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select>
<?php elseif(($type ?? '')==='textarea'): ?><textarea id="<?php echo e($fieldId); ?>" name="<?php echo e($name); ?>" rows="<?php echo e($rows ?? 3); ?>" <?php if($required ?? true): echo 'required'; endif; ?>><?php echo e($value ?? ''); ?></textarea>
<?php else: ?><input id="<?php echo e($fieldId); ?>" name="<?php echo e($name); ?>" type="<?php echo e($type ?? 'text'); ?>" value="<?php echo e(($type ?? '')==='password' ? '' : ($value ?? '')); ?>" <?php if($required ?? true): echo 'required'; endif; ?> <?php if(isset($placeholder)): ?> placeholder="<?php echo e($placeholder); ?>" <?php endif; ?> <?php if(isset($min)): ?> min="<?php echo e($min); ?>" <?php endif; ?> <?php if(isset($step)): ?> step="<?php echo e($step); ?>" <?php endif; ?> <?php if(isset($autocomplete)): ?> autocomplete="<?php echo e($autocomplete); ?>" <?php endif; ?>><?php endif; ?>
<?php if(isset($hint)): ?><small><?php echo e($hint); ?></small><?php endif; ?></div>
